const C = D.clean;
const RAW = C.INPUT_RECORDS, VALID = C.VALID_RECORDS;
const jobs = D.jobs.filter(j => j.name);
const byLog = Object.fromEntries(D.jobs.map(j => [j.log, j]));
const cleanJob = byLog['10_job_clean'];
const revJob = byLog['14_job_revenue'];
const routeJob = byLog['17_job_routes'];
const benchJob = byLog['25_job_revenue_bench'];
const tinyJob = byLog['26_bench_hadoop_tiny'];
const halfJob = byLog['27_bench_hadoop_half'];
const stage2 = jobs.filter(j => /^1[1-5]-/.test(j.name));
const pipelineJobs = jobs.filter(j => !/^BENCH/.test(j.name));

const rejected = RAW - VALID;
const rej = k => C[k] || 0;
const rejPct = k => (rej(k) / RAW * 100);
const topZonesShare = D.top10_zones.reduce((a, z) => a + z.trips, 0) / VALID * 100;
const routeCombIn = routeJob.comb_in || 0, routeCombOut = routeJob.comb_out || 0;

